5	import { schemas } from "@workspace/api-zod";
6	
7	const router: IRouter = Router();
8	
9	async function requireAdmin(req: Request): Promise<boolean> {
10	  const { userId } = getAuth(req);
11	  if (!userId) return false;
12	  const [u] = await db
13	    .select()
14	    .from(appUsers)
15	    .where(eq(appUsers.clerkUserId, userId));
16	  return u?.role === "admin";
17	}
18	
19	router.get("/admin/users", async (req, res): Promise<void> => {
20	  if (!(await requireAdmin(req))) {
21	    res.status(403).json({ error: "Admin access required" });
22	    return;
23	  }
24	  const rows = await db
25	    .select({
26	      id: appUsers.id,
27	      clerkUserId: appUsers.clerkUserId,
28	      email: appUsers.email,
29	      firstName: appUsers.firstName,
30	      lastName: appUsers.lastName,
31	      imageUrl: appUsers.imageUrl,
32	      role: appUsers.role,
33	      createdAt: appUsers.createdAt,
34	      projectCount: sql<number>`(SELECT count(*)::int FROM ${projects} WHERE ${projects.ownerUserId} = ${appUsers.id})`,
35	    })
36	    .from(appUsers)
37	    .orderBy(desc(appUsers.createdAt));
38	  res.json(schemas.ListAdminUsersResponse.parse(rows));
39	});
40	
41	router.patch("/admin/users/:userId", async (req, res): Promise<void> => {
42	  if (!(await requireAdmin(req))) {
43	    res.status(403).json({ error: "Admin access required" });
44	    return;
45	  }
46	  const params = schemas.UpdateAdminUserParams.safeParse(req.params);
47	  if (!params.success) {
48	    res.status(400).json({ error: params.error.message });
49	    return;
50	  }
51	  const parsed = schemas.UpdateAdminUserBody.safeParse(req.body);
52	  if (!parsed.success) {
53	    res.status(400).json({ error: parsed.error.message });
54	    return;
55	  }
56	  await db
57	    .update(appUsers)
58	    .set({ role: parsed.data.role ?? "user" })
59	    .where(eq(appUsers.id, params.data.userId));
60	  const [row] = await db
61	    .select({
62	      id: appUsers.id,
63	      clerkUserId: appUsers.clerkUserId,
64	      email: appUsers.email,
65	      firstName: appUsers.firstName,
66	      lastName: appUsers.lastName,
67	      imageUrl: appUsers.imageUrl,
68	      role: appUsers.role,
69	      createdAt: appUsers.createdAt,
70	      projectCount: sql<number>`(SELECT count(*)::int FROM ${projects} WHERE ${projects.ownerUserId} = ${appUsers.id})`,
71	    })
72	    .from(appUsers)
73	    .where(eq(appUsers.id, params.data.userId));
74	  if (!row) {
75	    res.status(404).json({ error: "User not found" });
76	    return;
77	  }
78	  res.json(schemas.UpdateAdminUserResponse.parse(row));
79	});
80	
81	router.delete("/admin/users/:userId", async (req, res): Promise<void> => {
82	  if (!(await requireAdmin(req))) {
83	    res.status(403).json({ error: "Admin access required" });
84	    return;
85	  }
86	  const params = schemas.DeleteAdminUserParams.safeParse(req.params);
87	  if (!params.success) {
88	    res.status(400).json({ error: params.error.message });
89	    return;
90	  }
91	  await db.delete(appUsers).where(eq(appUsers.id, params.data.userId));
92	  res.sendStatus(204);
93	});
