33	  const parsed = schemas.CreateProjectBody.safeParse(req.body);
34	  if (!parsed.success) {
35	    res.status(400).json({ error: parsed.error.message });
36	    return;
37	  }
38	  const { userId } = getAuth(req);
39	  let ownerUserId: number | undefined;
