93	  res.json(
94	    schemas.UpdateAiSettingsResponse.parse({
95	      provider: pref?.provider ?? "anthropic",
96	      model: pref?.model ?? null,
97	      hasApiKey: Boolean(pref?.apiKey),
98	    }),
99	  );
100	});
