16	export async function requireAuth(
17	  req: Request,
18	  res: Response,
19	  next: NextFunction,
20	): Promise<void> {
21	  const { userId } = getAuth(req);
22	  if (!userId) {
23	    res.status(401).json({ error: "Unauthorized" });
24	    return;
25	  }
26	  try {
27	    const [u] = await db
28	      .select()
29	      .from(appUsers)
30	      .where(eq(appUsers.clerkUserId, userId));
31	    if (!u) {
32	      res.status(401).json({ error: "Unauthorized" });
33	      return;
34	    }
35	    req.appUserId = u.id;
36	    req.appUserRole = u.role;
37	    next();
38	  } catch (err) {
39	    req.log.error({ err }, "auth check failed");
40	    res.status(500).json({ error: "Auth error" });
41	  }
42	}
