44	export async function requireProjectAccess(
45	  req: Request,
46	  res: Response,
47	  next: NextFunction,
48	): Promise<void> {
49	  const projectIdRaw = req.params.projectId;
50	  const projectIdStr = Array.isArray(projectIdRaw) ? projectIdRaw[0] : projectIdRaw;
51	  const projectId = parseInt(projectIdStr || "0", 10);
52	  if (!projectId || Number.isNaN(projectId)) {
53	    res.status(400).json({ error: "Invalid project id" });
54	    return;
55	  }
56	  if (!req.appUserId) {
57	    res.status(401).json({ error: "Unauthorized" });
58	    return;
59	  }
60	  try {
61	    const [proj] = await db
62	      .select()
63	      .from(projects)
64	      .where(eq(projects.id, projectId));
65	    if (!proj) {
66	      res.status(404).json({ error: "Project not found" });
67	      return;
68	    }
69	    const isOwner = proj.ownerUserId === req.appUserId;
70	    const isAdmin = req.appUserRole === "admin";
71	    let isWorkspaceMember = false;
72	    if (proj.workspaceId) {
73	      const [m] = await db
74	        .select({ id: workspaceMembers.id, status: workspaceMembers.status })
75	        .from(workspaceMembers)
76	        .where(
77	          and(
78	            eq(workspaceMembers.workspaceId, proj.workspaceId),
79	            eq(workspaceMembers.userId, req.appUserId),
80	          ),
81	        );
82	      if (m && m.status === "active") isWorkspaceMember = true;
83	    }
84	    if (!isOwner && !isAdmin && !isWorkspaceMember) {
85	      res.status(403).json({ error: "Forbidden" });
86	      return;
87	    }
88	    next();
89	  } catch (err) {
90	    req.log.error({ err }, "project access check failed");
91	    res.status(500).json({ error: "Access check error" });
92	  }
93	}
