95	export async function requireAdmin(
96	  req: Request,
97	  res: Response,
98	  next: NextFunction,
99	): Promise<void> {
100	  if (!req.appUserId) {
101	    res.status(401).json({ error: "Unauthorized" });
102	    return;
103	  }
104	  if (req.appUserRole !== "admin") {
105	    res.status(403).json({ error: "Forbidden" });
106	    return;
107	  }
108	  next();
109	}
