176	export async function complete(
177	  req: Request,
178	  opts: CompleteOptions,
179	): Promise<string> {
180	  const choice = await pickProvider(
181	    req,
182	    opts.kind ?? "structured",
183	    opts.preferFast ?? false,
184	  );
185	  const max = opts.maxTokens ?? 2048;
186	  const clients = await resolveClients(req, choice);
187	
