305	export function tryParseJsonArray<T = unknown>(text: string): T[] {
306	  const cleaned = text
307	    .trim()
308	    .replace(/^```json\s*/i, "")
309	    .replace(/^```/, "")
310	    .replace(/```$/, "")
311	    .trim();
312	  try {
313	    const v = JSON.parse(cleaned);
314	    return Array.isArray(v) ? v : [];
315	  } catch {
316	    const match = cleaned.match(/\[[\s\S]*\]/);
317	    if (match) {
318	      try {
319	        const v = JSON.parse(match[0]);
320	        return Array.isArray(v) ? v : [];
321	      } catch {
322	        return [];
323	      }
324	    }
325	    return [];
326	  }
327	}
