396	// Best-effort repair for JSON that was cut off mid-output (token cap, network).
397	// Collects every "safe cut" position (after a closed string, value, or `}`/`]`)
398	// while scanning, then attempts to close from the latest safe point and walks
399	// backwards through prior safe points until JSON.parse succeeds.
400	function repairTruncatedJsonObject(text: string): string | null {
401	  const start = text.indexOf("{");
402	  if (start === -1) return null;
403	  const buf = text.slice(start);
404	  const safePoints: number[] = []; // indices (exclusive end) where it is safe to cut
405	  let inString = false;
406	  let escape = false;
407	  for (let i = 0; i < buf.length; i++) {
408	    const ch = buf[i];
409	    if (escape) {
410	      escape = false;
411	      continue;
412	    }
413	    if (inString) {
414	      if (ch === "\\") {
415	        escape = true;
416	        continue;
417	      }
418	      if (ch === '"') {
419	        inString = false;
420	        safePoints.push(i + 1);
421	      }
422	      continue;
423	    }
424	    if (ch === '"') {
425	      inString = true;
426	      continue;
427	    }
428	    if (ch === "}" || ch === "]") {
429	      safePoints.push(i + 1);
430	      continue;
431	    }
432	    if (ch === ",") {
433	      safePoints.push(i); // cut BEFORE the comma so we strip it
434	    }
435	  }
436	  if (safePoints.length === 0) return null;
437	  // Try latest safe point first, then walk back.
438	  for (let k = safePoints.length - 1; k >= 0; k--) {
439	    const cutAt = safePoints[k];
440	    let candidate = buf.slice(0, cutAt).replace(/,\s*$/, "");
441	    const state = scanJsonState(candidate);
442	    if (state.inString) candidate += '"';
443	    candidate += state.stack.reverse().join("");
444	    try {
445	      JSON.parse(candidate);
446	      return candidate;
447	    } catch {
448	      // try earlier point
449	    }
450	  }
451	  return null;
452	}
453	
454	function scanJsonState(text: string): { stack: string[]; inString: boolean } {
455	  const stack: string[] = [];
456	  let inString = false;
457	  let escape = false;
458	  for (let i = 0; i < text.length; i++) {
459	    const ch = text[i];
460	    if (escape) {
461	      escape = false;
462	      continue;
463	    }
464	    if (inString) {
465	      if (ch === "\\") {
466	        escape = true;
467	        continue;
468	      }
469	      if (ch === '"') inString = false;
470	      continue;
471	    }
472	    if (ch === '"') {
473	      inString = true;
474	      continue;
475	    }
476	    if (ch === "{") stack.push("}");
477	    else if (ch === "[") stack.push("]");
478	    else if (ch === "}" || ch === "]") stack.pop();
479	  }
480	  return { stack, inString };
481	}
