16	export async function ensurePersonalWorkspace(userId: number): Promise<Workspace> {
17	  const [user] = await db.select().from(appUsers).where(eq(appUsers.id, userId));
18	
19	  // Fast path: a personal workspace already exists for this user.
20	  const [existing] = await db
21	    .select()
22	    .from(workspaces)
23	    .where(and(eq(workspaces.ownerUserId, userId), eq(workspaces.isPersonal, 1)));
24	
25	  let ws: Workspace;
26	  if (existing) {
27	    ws = existing;
28	  } else {
29	    // Race-safe create: rely on the partial-unique index (one personal ws per owner).
30	    const display = user?.firstName ? `${user.firstName}'s workspace` : "Personal workspace";
31	    const baseSlugRoot = user?.firstName ? slugify(user.firstName) : `personal-${userId}`;
32	    let attempt = 0;
33	    let created: Workspace | undefined;
34	    while (attempt < 5 && !created) {
35	      attempt += 1;
36	      const slug = await ensureUniqueSlug(baseSlugRoot, async (s) => {
37	        const [hit] = await db.select({ id: workspaces.id }).from(workspaces).where(eq(workspaces.slug, s));
38	        return Boolean(hit);
39	      });
40	      try {
41	        const rows = await db
42	          .insert(workspaces)
43	          .values({ slug, name: display, ownerUserId: userId, isPersonal: 1 })
44	          .returning();
45	        created = rows[0];
46	      } catch (err) {
47	        if (!isUniqueViolation(err)) throw err;
48	        // Either slug raced, or the personal-per-owner unique fired; re-check first.
49	        const [racedExisting] = await db
50	          .select()
51	          .from(workspaces)
52	          .where(and(eq(workspaces.ownerUserId, userId), eq(workspaces.isPersonal, 1)));
53	        if (racedExisting) {
54	          created = racedExisting;
55	        }
56	        // else: slug collision, loop and try a fresh slug
57	      }
58	    }
59	    if (!created) throw new Error("Failed to create personal workspace after retries");
60	    ws = created;
61	  }
62	
63	  // Ensure owner member row exists.
64	  try {
65	    await db
66	      .insert(workspaceMembers)
67	      .values({
68	        workspaceId: ws.id,
69	        userId,
70	        role: "owner",
71	        status: "active",
72	        joinedAt: new Date(),
73	      })
74	      .onConflictDoNothing();
75	  } catch (err) {
76	    if (!isUniqueViolation(err)) throw err;
77	  }
78	
79	  // Migrate any of the user's projects without a workspace.
80	  const orphans = await db
81	    .select()
82	    .from(projects)
83	    .where(and(eq(projects.ownerUserId, userId), isNull(projects.workspaceId)));
84	  for (const p of orphans) {
85	    let attempt = 0;
86	    while (attempt < 5) {
87	      attempt += 1;
88	      const slug = await ensureUniqueSlug(p.name, async (s) => {
89	        const [hit] = await db
90	          .select({ id: projects.id })
91	          .from(projects)
92	          .where(and(eq(projects.workspaceId, ws.id), eq(projects.slug, s)));
93	        return Boolean(hit);
94	      });
95	      try {
96	        await db.update(projects).set({ workspaceId: ws.id, slug }).where(eq(projects.id, p.id));
97	        break;
98	      } catch (err) {
99	        if (!isUniqueViolation(err)) throw err;
100	        // raced — try a different slug
101	      }
102	    }
103	  }
104	  return ws;
105	}
