177	    const idbProvider = new IndexeddbPersistence(`gameforge-${projectId}-${key}`, ydoc);
178	    
179	    const wsUrl = import.meta.env.VITE_WS_URL || "ws://localhost:1234";
180	    const wsProvider = new WebsocketProvider(wsUrl, `gameforge-${projectId}-${key}`, ydoc);
181	
182	    const ytext = ydoc.getText(key);
183	    
184	    const updateText = () => {
185	      setText(ytext.toString());
186	    };
187	
188	    ytext.observe(updateText);
189	    updateText();
190	
191	    return () => {
192	      ytext.unobserve(updateText);
193	      wsProvider.destroy();
194	      idbProvider.destroy();
195	      ydoc.destroy();
196	    };
197	  }, [projectId, key]);
198	
199	  const setTextContent = useCallback((newText: string) => {
