7	const ALGO = "aes-256-gcm";
8	const IV_LEN = 12;
9	
10	export type WorkspaceProvider = "anthropic" | "openai" | "gemini" | "openrouter";
11	export const ALL_PROVIDERS: WorkspaceProvider[] = ["anthropic", "openai", "gemini", "openrouter"];
