13	export class AiProviderDisabledError extends Error {
14	  status = 503 as const;
15	  provider: WorkspaceProvider;
16	  constructor(provider: WorkspaceProvider) {
17	    super(`AI provider "${provider}" is disabled for this workspace.`);
18	    this.name = "AiProviderDisabledError";
