23	export class AiProviderKeyDecryptError extends Error {
24	  status = 500 as const;
25	  provider: WorkspaceProvider;
26	  constructor(provider: WorkspaceProvider) {
27	    super(
28	      `Stored BYOK API key for provider "${provider}" could not be decrypted (SESSION_SECRET may have rotated). Re-enter the key in workspace settings.`,
29	    );
30	    this.name = "AiProviderKeyDecryptError";
31	    this.provider = provider;
32	  }
