34	
35	function getMasterKey(): Buffer {
36	  const secret = process.env.SESSION_SECRET;
37	  if (!secret) throw new Error("SESSION_SECRET not configured");
38	  return crypto.createHash("sha256").update(secret).digest();
39	}
40	
41	export function encryptApiKey(plain: string): string {
42	  const key = getMasterKey();
43	  const iv = crypto.randomBytes(IV_LEN);
44	  const cipher = crypto.createCipheriv(ALGO, key, iv);
45	  const enc = Buffer.concat([cipher.update(plain, "utf8"), cipher.final()]);
46	  const tag = cipher.getAuthTag();
47	  return `${iv.toString("base64")}.${tag.toString("base64")}.${enc.toString("base64")}`;
48	}
49	
50	export function decryptApiKey(payload: string): string | null {
51	  try {
52	    const [ivB64, tagB64, dataB64] = payload.split(".");
53	    if (!ivB64 || !tagB64 || !dataB64) return null;
54	    const key = getMasterKey();
55	    const iv = Buffer.from(ivB64, "base64");
56	    const tag = Buffer.from(tagB64, "base64");
57	    const data = Buffer.from(dataB64, "base64");
58	    const decipher = crypto.createDecipheriv(ALGO, key, iv);
59	    decipher.setAuthTag(tag);
60	    const dec = Buffer.concat([decipher.update(data), decipher.final()]);
61	    return dec.toString("utf8");
62	  } catch {
63	    return null;
64	  }
65	}
