73	export async function getWorkspaceProviderSettings(
74	  workspaceId: number,
75	  provider: WorkspaceProvider,
76	): Promise<ResolvedProviderSettings> {
77	  const [row] = await db
78	    .select()
79	    .from(workspaceAiSettings)
80	    .where(
81	      and(
82	        eq(workspaceAiSettings.workspaceId, workspaceId),
83	        eq(workspaceAiSettings.provider, provider),
84	      ),
85	    );
86	  if (!row) {
87	    return { enabled: true, apiKey: null, hasKey: false };
88	  }
89	  if (!row.encryptedKey) {
90	    return { enabled: row.enabled, apiKey: null, hasKey: false };
91	  }
92	  const key = decryptApiKey(row.encryptedKey);
93	  if (key === null) {
94	    throw new AiProviderKeyDecryptError(provider);
95	  }
96	  return { enabled: row.enabled, apiKey: key, hasKey: true };
97	}
