196	export async function getWorkspaceIdForRequest(req: Request): Promise<number | null> {
197	  if (req.workspace?.id) return req.workspace.id;
198	  const projectIdParam = req.params?.projectId;
199	  if (projectIdParam) {
200	    const projectId = Number(projectIdParam);
201	    if (Number.isFinite(projectId)) {
202	      const [p] = await db
203	        .select({ workspaceId: projects.workspaceId })
204	        .from(projects)
205	        .where(eq(projects.id, projectId));
206	      if (p?.workspaceId) return p.workspaceId;
207	    }
208	  }
209	  return null;
210	}
