405	// Compare two versions. Declared BEFORE the `:versionId` route so Express
406	// matches `compare` as a literal segment rather than treating it as an id.
407	router.get(
408	  "/projects/:projectId/versions/compare",
409	  async (req, res): Promise<void> => {
410	    if (!currentUserId(req)) {
411	      res.status(401).json({ error: "Unauthorized" });
412	      return;
413	    }
414	    const v1 = parseInt(String(req.query.v1 ?? "0"), 10);
415	    const v2 = parseInt(String(req.query.v2 ?? "0"), 10);
416	    if (!v1 || !v2) {
417	      res.status(400).json({ error: "v1 and v2 query params are required" });
418	      return;
419	    }
420	    try {
421	      const [version1] = await db
422	        .select()
423	        .from(projectVersions)
424	        .where(eq(projectVersions.id, v1))
425	        .limit(1);
426	      const [version2] = await db
427	        .select()
428	        .from(projectVersions)
429	        .where(eq(projectVersions.id, v2))
430	        .limit(1);
431	      if (!version1 || !version2) {
432	        res.status(404).json({ error: "One or more versions not found" });
433	        return;
434	      }
435	      // `snapshot` is a JSONB column typed as `unknown` — narrow with a Record
436	      // cast since we just compare presence of the four known top-level keys.
437	      const s1 = (version1.snapshot ?? {}) as Record<string, unknown>;
438	      const s2 = (version2.snapshot ?? {}) as Record<string, unknown>;
439	      const diff = {
440	        entities: JSON.stringify(s1.entities) !== JSON.stringify(s2.entities),
441	        rules: JSON.stringify(s1.rules) !== JSON.stringify(s2.rules),
442	        players: JSON.stringify(s1.players) !== JSON.stringify(s2.players),
443	        notes: JSON.stringify(s1.notes) !== JSON.stringify(s2.notes),
444	      };
445	      res.json({ diff });
446	    } catch (err) {
447	      req.log.error({ err }, "compare versions failed");
448	      res.status(500).json({ error: "Failed to compare versions" });
449	    }
450	  },
451	);
