1	/**
2	 * Clerk Frontend API Proxy Middleware
3	 *
4	 * Proxies Clerk Frontend API requests through your domain, enabling Clerk
5	 * authentication on custom domains and .replit.app deployments without
6	 * requiring CNAME DNS configuration.
7	 *
8	 * AUTH CONFIGURATION: To manage users, enable/disable login providers
9	 * (Google, GitHub, etc.), change app branding, or configure OAuth credentials,
10	 * use the Auth pane in the workspace toolbar. There is no external Clerk
11	 * dashboard — all auth configuration is done through the Auth pane.
12	 *
13	 * IMPORTANT:
14	 * - Only active in production (Clerk proxying doesn't work for dev instances)
15	 * - Must be mounted BEFORE express.json() middleware
16	 *
17	 * Usage in app.ts:
18	 *   import { CLERK_PROXY_PATH, clerkProxyMiddleware } from "./middlewares/clerkProxyMiddleware";
19	 *   app.use(CLERK_PROXY_PATH, clerkProxyMiddleware());
20	 */
21	
22	import { createProxyMiddleware } from "http-proxy-middleware";
23	import type { RequestHandler } from "express";
24	
25	const CLERK_FAPI = "https://frontend-api.clerk.dev";
26	export const CLERK_PROXY_PATH = "/api/__clerk";
27	
28	export function clerkProxyMiddleware(): RequestHandler {
29	  // Only run proxy in production — Clerk proxying doesn't work for dev instances
30	  if (process.env.NODE_ENV !== "production") {
31	    return (_req, _res, next) => next();
32	  }
33	
34	  const secretKey = process.env.CLERK_SECRET_KEY;
35	  if (!secretKey) {
36	    return (_req, _res, next) => next();
37	  }
38	
39	  return createProxyMiddleware({
40	    target: CLERK_FAPI,
41	    changeOrigin: true,
42	    pathRewrite: (path: string) =>
43	      path.replace(new RegExp(`^${CLERK_PROXY_PATH}`), ""),
44	    on: {
45	      proxyReq: (proxyReq, req) => {
46	        const protocol = req.headers["x-forwarded-proto"] || "https";
47	        const host = req.headers.host || "";
48	        const proxyUrl = `${protocol}://${host}${CLERK_PROXY_PATH}`;
49	
50	        proxyReq.setHeader("Clerk-Proxy-Url", proxyUrl);
51	        proxyReq.setHeader("Clerk-Secret-Key", secretKey);
52	
53	        const xff = req.headers["x-forwarded-for"];
54	        const clientIp =
55	          (Array.isArray(xff) ? xff[0] : xff)?.split(",")[0]?.trim() ||
56	          req.socket?.remoteAddress ||
57	          "";
58	        if (clientIp) {
59	          proxyReq.setHeader("X-Forwarded-For", clientIp);
60	        }
61	      },
62	    },
63	  }) as RequestHandler;
64	}
